    await p
  })

  it('setVideoVolume 实时刷新正在播放的 video.volume', async () => {
    const p = playAvi({ src: '/extracted/videos/3.mp4' })
    const video = activeVideo()
    setVideoVolume(0.2)
    expect(video.volume).toBe(0.2)
    video.dispatchEvent(new Event('ended'))
